page_require(['ADMIN']);
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CRM de prospectos — Hache Natación</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f6fa;color:#172033;font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif}.wrap{max-width:1220px;margin:auto;padding:82px 14px 36px}.ey{font-size:11px;font-weight:900;letter-spacing:.12em;text-transform:uppercase;color:#567089}h1{margin:5px 0 6px;font-size:31px}.sub{color:#64748b;margin:0 0 18px;max-width:850px;line-height:1.45}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:16px 0}.card{background:#fff;border:1px solid #e5eaf0;border-radius:15px;padding:15px;box-shadow:0 7px 24px rgba(15,23,42,.035)}.card b{display:block;font-size:25px}.card span{font-size:12px;color:#64748b;font-weight:750}.filters{display:grid;grid-template-columns:minmax(220px,1fr) 190px 190px;gap:9px;margin:14px 0}.filters input,.filters select{width:100%;min-height:44px;border:1px solid #cbd5e1;border-radius:11px;background:#fff;padding:9px 11px;font:inherit}.panel{background:#fff;border:1px solid #e5eaf0;border-radius:17px;overflow:hidden;box-shadow:0 8px 28px rgba(15,23,42,.04)}table{width:100%;border-collapse:collapse}th,td{padding:12px 11px;text-align:left;border-bottom:1px solid #edf1f5;vertical-align:top}th{font-size:10px;text-transform:uppercase;letter-spacing:.06em;color:#64748b;background:#f8fafc}td{font-size:13px}.name{font-weight:850;font-size:14px}.muted{color:#64748b}.badge{display:inline-flex;padding:5px 8px;border-radius:999px;font-size:11px;font-weight:850;background:#edf2f7}.badge.inscrito{background:#dcfce7;color:#166534}.badge.inicio{background:#fef3c7;color:#92400e}.badge.meta{background:#e0e7ff;color:#3730a3}.badge.web{background:#dbeafe;color:#1d4ed8}.badge.direct{background:#e0f2fe;color:#0369a1}.badge.referral{background:#f3e8ff;color:#7e22ce}a{color:#2563eb;text-decoration:none;font-weight:750}.empty{padding:28px;text-align:center;color:#64748b}.note{margin:12px 0 0;color:#64748b;font-size:12px;line-height:1.5}.error{margin:14px 0;background:#fee2e2;color:#991b1b;padding:12px;border-radius:11px;display:none}.pager{display:flex;align-items:center;justify-content:center;gap:10px;margin:14px 0}.pager button{border:1px solid #cbd5e1;background:#fff;border-radius:10px;padding:9px 13px;font-weight:800;cursor:pointer}.pager button:disabled{opacity:.45;cursor:default}.pager span{font-size:13px;color:#64748b;font-weight:750}@media(max-width:900px){.summary{grid-template-columns:repeat(2,1fr)}.filters{grid-template-columns:1fr}.panel{background:transparent;border:0;box-shadow:none}table,thead,tbody,tr,th,td{display:block}thead{display:none}tr{background:#fff;border:1px solid #e5eaf0;border-radius:15px;margin-bottom:10px;padding:8px}td{border:0;padding:7px 9px}td:before{content:attr(data-label);display:block;font-size:9px;text-transform:uppercase;font-weight:900;color:#94a3b8;margin-bottom:2px}}@media(max-width:540px){.summary{grid-template-columns:1fr 1fr}.wrap{padding-top:76px}h1{font-size:27px}}</style></head><body><main class="wrap"><div class="ey">Fase 4 · seguimiento interno</div><h1>CRM de prospectos</h1><p class="sub">Vista de solo lectura construida con datos ya registrados por Sharky. No cambia el funnel, no confirma elecciones por inferencia y no envía mensajes.</p><section class="summary"><div class="card"><b id="sTotal">—</b><span>Contactos en CRM</span></div><div class="card"><b id="sProspectos">—</b><span>Prospectos en esta página</span></div><div class="card"><b id="sIniciada">—</b><span>Inscripción iniciada en esta página</span></div><div class="card"><b id="sInscritos">—</b><span>Inscritos en esta página</span></div></section><div class="filters"><input id="q" type="search" placeholder="Buscar en todo el CRM por nombre o WhatsApp"><select id="source"><option value="">Todas las fuentes (página)</option><option value="meta_ad">Meta Ads</option><option value="web">Web</option><option value="direct">WhatsApp directo</option><option value="referral">Referencia</option><option value="none">Sin fuente persistente</option></select><select id="stage"><option value="">Todos los estados (página)</option><option value="PROSPECTO">Prospecto</option><option value="INSCRIPCION_INICIADA">Inscripción iniciada</option><option value="INSCRITO">Inscrito</option></select></div><div id="err" class="error"></div><section class="panel"><table><thead><tr><th>Contacto</th><th>Fuente</th><th>Producto / sede</th><th>Estado</th><th>Último contacto</th><th>Campaña / origen</th></tr></thead><tbody id="rows"><tr><td colspan="6" class="empty">Cargando…</td></tr></tbody></table></section><div class="pager"><button id="prev" type="button">← Anterior</button><span id="pageInfo">Página —</span><button id="next" type="button">Siguiente →</button></div><p class="note">La búsqueda por nombre o WhatsApp recorre todo el CRM; los filtros de fuente y estado refinan la página cargada. Cuando el estado conversacional ya expiró, producto, sede o fuente web/directa pueden aparecer como no disponibles. El CRM no reconstruye esos datos por intuición. Meta Ads puede conservarse cuando existe referral persistente.</p></main><script>
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let data=[],currentPage=1,pages=1,searchTimer=null;
const fmt=v=>{if(!v)return'—';const d=new Date(String(v).replace(' ','T'));return Number.isNaN(d.getTime())?String(v):new Intl.DateTimeFormat('es-MX',{dateStyle:'medium',timeStyle:'short'}).format(d)};
const stageLabel=s=>s==='INSCRITO'?'Inscrito':s==='INSCRIPCION_INICIADA'?'Inscripción iniciada':'Prospecto';
const stageClass=s=>s==='INSCRITO'?'inscrito':s==='INSCRIPCION_INICIADA'?'inicio':'';
const sourceClass=s=>['meta_ad','web','direct','referral'].includes(s||'')?(s==='meta_ad'?'meta':s):'';
function render(){const sv=source.value,st=stage.value;const filtered=data.filter(r=>{const fs=sv===''||((sv==='none')?r.fuente===null:r.fuente===sv);const fst=st===''||r.estado_crm===st;return fs&&fst});rows.innerHTML=filtered.length?filtered.map(r=>`<tr><td data-label="Contacto"><div class="name">${esc(r.nombre)}</div><div class="muted">${esc(r.whatsapp||'Sin número disponible')}</div>${r.alumno_id?`<div><a href="/ficha-alumno.php?id=${encodeURIComponent(r.alumno_id)}">Abrir alumno</a></div>`:''}</td><td data-label="Fuente"><span class="badge ${sourceClass(r.fuente)}">${esc(r.fuente_etiqueta)}</span></td><td data-label="Producto / sede"><div>${esc(r.producto_etiqueta)}</div><div class="muted">${esc(r.sede||'Sede no confirmada/disponible')}</div></td><td data-label="Estado"><span class="badge ${stageClass(r.estado_crm)}">${esc(stageLabel(r.estado_crm))}</span>${r.registro_estado&&r.estado_crm!=='INSCRITO'?`<div class="muted">Último registro: ${esc(r.registro_estado)}</div>`:''}</td><td data-label="Último contacto"><div>${esc(fmt(r.ultimo_contacto))}</div><div class="muted">${esc(r.ultimo_contacto_tipo||'')}</div></td><td data-label="Campaña / origen"><div>${esc(r.campana||'—')}</div>${r.estado_conversacion_disponible?'':`<div class="muted">Estado conversacional expirado/no disponible</div>`}</td></tr>`).join(''):`<tr><td colspan="6" class="empty">No hay resultados con esos filtros en esta página.</td></tr>`}
async function load(){try{err.style.display='none';const params=new URLSearchParams({page:String(currentPage),per_page:'50'});const term=q.value.trim();if(term)params.set('q',term);const r=await fetch('/api/prospectos.php?'+params.toString(),{credentials:'same-origin',cache:'no-store'}),j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'No se pudo cargar');data=Array.isArray(j.prospectos)?j.prospectos:[];currentPage=Number(j.paginacion?.page||1);pages=Math.max(1,Number(j.paginacion?.pages||1));sTotal.textContent=j.resumen?.total_crm??'0';sProspectos.textContent=j.resumen?.prospectos_pagina??'0';sIniciada.textContent=j.resumen?.inscripcion_iniciada_pagina??'0';sInscritos.textContent=j.resumen?.inscritos_pagina??'0';pageInfo.textContent=`Página ${currentPage} de ${pages}${term?` · ${Number(j.paginacion?.total||0)} coincidencias`:''}`;prev.disabled=currentPage<=1;next.disabled=currentPage>=pages;render()}catch(e){err.style.display='block';err.textContent=e.message||'No se pudo cargar el CRM';rows.innerHTML='<tr><td colspan="6" class="empty">Sin datos.</td></tr>'}}
q.addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{currentPage=1;load()},300)});source.addEventListener('input',render);stage.addEventListener('input',render);prev.onclick=()=>{if(currentPage>1){currentPage--;load()}};next.onclick=()=>{if(currentPage<pages){currentPage++;load()}};load();
</script></body></html>